CREATE SET TABLE MDP01_META.META_ETL_JOB_STEP ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      etl_job_step_id BIGINT NOT NULL GENERATED ALWAYS AS IDENTITY           (START WITH 1             INCREMENT BY 1             MINVALUE -999999999999999999             MAXVALUE 999999999999999999             NO CYCLE),      etl_job_id INTEGER NOT NULL,      step_name VARCHAR(200) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      step_order INTEGER NOT NULL,      step_category VARCHAR(50) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      sql_template_path VARCHAR(500) CHARACTER SET LATIN CASESPECIFIC,      sql_inline CLOB(16777216) CHARACTER SET UNICODE,      python_module VARCHAR(200) CHARACTER SET LATIN CASESPECIFIC,      python_function VARCHAR(100) CHARACTER SET LATIN CASESPECIFIC,      parameters CLOB(16777216) CHARACTER SET UNICODE,      condition_sql VARCHAR(1000) CHARACTER SET LATIN CASESPECIFIC,      skip_on_empty CHAR(1) CHARACTER SET LATIN CASESPECIFIC CHECK ( skip_on_empty  IN ('Y','N') ) DEFAULT 'N',      is_critical CHAR(1) CHARACTER SET LATIN CASESPECIFIC CHECK ( is_critical  IN ('Y','N') ) DEFAULT 'Y',      rollback_on_error CHAR(1) CHARACTER SET LATIN CASESPECIFIC CHECK ( rollback_on_error  IN ('Y','N') ) DEFAULT 'Y',      is_active CHAR(1) CHARACTER SET LATIN CASESPECIFIC CHECK ( is_active  IN ('Y','N') ) DEFAULT 'Y',      beschreibung VARCHAR(2000) CHARACTER SET LATIN CASESPECIFIC,      created_by VARCHAR(200) CHARACTER SET LATIN CASESPECIFIC DEFAULT USER ,      create_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      modified_by VARCHAR(200) CHARACTER SET LATIN CASESPECIFIC DEFAULT USER ,      last_alter_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      RETRY_COUNT INTEGER DEFAULT 3 ,      TIMEOUT_SECONDS INTEGER DEFAULT 300 )PRIMARY INDEX ( etl_job_step_id );